create table if not exists public.site_settings (id text primary key default 'main', data jsonb not null default '{}'::jsonb, updated_at timestamptz default now());
create table if not exists public.shows (id bigint generated by default as identity primary key, show_date date not null, show_time time, city text not null, state text, event_name text, place text, ticket_url text, published boolean default true, created_at timestamptz default now());
create table if not exists public.videos (id bigint generated by default as identity primary key, title text, youtube_url text not null, description text, published boolean default true, sort_order int default 0, created_at timestamptz default now());
alter table public.site_settings enable row level security; alter table public.shows enable row level security; alter table public.videos enable row level security;
create policy "public read settings" on public.site_settings for select using (true);
create policy "public read shows" on public.shows for select using (published = true);
create policy "public read videos" on public.videos for select using (published = true);
create policy "auth manage settings" on public.site_settings for all to authenticated using (true) with check (true);
create policy "auth manage shows" on public.shows for all to authenticated using (true) with check (true);
create policy "auth manage videos" on public.videos for all to authenticated using (true) with check (true);
